import cors from "cors";
import express from "express";
import productsRouter from "./routes/products.js";
import categoryRoutes from "./routes/catetories.js";
import brandRoutes from "./routes/brands.js";
import searchRouter from "./routes/search.js";
import ordersRouter from "./routes/orders.js";
import sellerOrdersRouter from "./routes/sellerOrders.js";
import wishlistRoutes from "./routes/wishlist.js";
import couponsRouter from "./routes/coupons.js";
import aiRouter from "./routes/aiChat.js";
import aiProductSearchRouter from "./routes/aiProductSearch.js";
import stripeRoutes from "./routes/stripe.js";
import addressRoutes from "./routes/address.js";
import sellerDashboardRouter from "./routes/sellerDashboard.js";
import notificationsRouter from "./routes/notifications.js";
import paymentMethodsRouter from "./routes/paymentMethods.js";
import reviewsRouter from "./routes/reviews.js";
import adminCustomersRouter from "./routes/adminCustomers.js";
import adminProductsRouter from "./routes/adminProducts.js";
import accountRouter from "./routes/account.js";
import adminCouponsRouter from "./routes/adminCoupons.js";
import adminNotificationsRouter from "./routes/adminNotifications.js";
import adminReportsRouter from "./routes/adminReports.js";
import adminUsersRouter from "./routes/adminUsers.js";
const app = express();
app.use(cors({ origin: true, credentials: true }));
app.use(express.json());
app.get("/", (req, res) => {
    res.json({
        success: true,
        message: "welcome"
    });
});
app.use("/api/v1/products", productsRouter);
app.use("/api/v1/categories", categoryRoutes);
app.use("/api/v1/brands", brandRoutes);
app.use("/api/v1/search", searchRouter);
app.use("/api/v1/orders", ordersRouter);
app.use("/api/v1/seller/orders", sellerOrdersRouter);
app.use("/api/v1/wishlist", wishlistRoutes);
app.use("/api/v1/coupons", couponsRouter);
app.use("/api/v1/ai", aiRouter);
app.use("/api/v1/ai/products", aiProductSearchRouter);
app.use("/api/v1/stripe", stripeRoutes);
app.use('/api/v1/addresses', addressRoutes);
app.use("/api/v1/seller/dashboard", sellerDashboardRouter);
app.use("/api/v1/notifications", notificationsRouter);
app.use("/api/v1/payment-methods", paymentMethodsRouter);
app.use("/api/v1/reviews", reviewsRouter);
app.use("/api/v1/admin/customers", adminCustomersRouter);
app.use("/api/v1/admin/products", adminProductsRouter);
app.use("/api/v1/admin/coupons", adminCouponsRouter);
app.use("/api/v1/admin/notifications", adminNotificationsRouter);
app.use("/api/v1/admin/reports", adminReportsRouter);
app.use("/api/v1/admin/users", adminUsersRouter);
app.use("/api/v1/account", accountRouter);
export default app;
